<?php $title='Orçamentos';require __DIR__.'/_top.php';?><div class="page-heading"><div><p class="eyebrow">Snapshot imutável</p><h1>Orçamentos</h1></div></div><div class="detail-grid"><section class="admin-panel"><h2>Novo orçamento</h2><form class="admin-form" method="post" action="<?= e(base_url('admin/operacoes/quote-create')) ?>"><?= csrf_field() ?><label>Cliente<input name="customer_name"></label><label>E-mail<input type="email" name="customer_email"></label><label>Telefone<input name="customer_phone"></label><label>Check-in<input type="date" name="checkin" required></label><label>Check-out<input type="date" name="checkout" required></label><label>Hóspedes<input type="number" name="guests" min="1" max="10" required></label><label>Pets<input type="number" name="pets" min="0" value="0"></label><label>Cupom<input name="coupon"></label><button class="admin-primary">Calcular e salvar snapshot</button></form></section><section class="admin-panel"><h2>Histórico</h2><?php if(!$quotes):?><p class="empty-state">Nenhum orçamento.</p><?php endif;?><?php foreach($quotes as $quote):?><div class="block-row"><div><strong><?= e($quote['code']) ?> · <?= money($quote['total']) ?></strong><small><?= e($quote['checkin']) ?>–<?= e($quote['checkout']) ?> · <?= (int)$quote['guests'] ?> hóspedes · <?= e($quote['status']) ?></small></div></div><?php endforeach;?></section></div><?php require __DIR__.'/_bottom.php';?>
